  cubeOutline, chevronDown 
} from 'ionicons/icons';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import { useUser } from '../contexts/UserContext';
import {
  PosRewardCatalogItem,
  getAllPosRewardCatalogItems,
  createPosRewardCatalogItem,
  updatePosRewardCatalogItem,
  deletePosRewardCatalogItem,
} from '../api/posRewardCatalogItemApi';
import './PosRewardCatalogItemPage.css';

const toHermosillo = (utc: string | undefined): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

interface FormState {
  name: string;
  rewardType: 'Discount' | 'Product';
  requiredPoints: number | '';
  discountValue: number | '';
  freeProductId: number | '';
  isActive: boolean;
  description: string;
}

const PosRewardCatalogItemPage: React.FC = () => {
  const { companyId } = useUser();

  const [catalogItems, setCatalogItems] = useState<PosRewardCatalogItem[]>([]);
  const [filteredCatalogItems, setFilteredCatalogItems] = useState<PosRewardCatalogItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string>('');
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastColor, setToastColor] = useState<'success' | 'danger'>('success');

  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentCatalogItem, setCurrentCatalogItem] = useState<PosRewardCatalogItem | null>(null);
  const [formState, setFormState] = useState<FormState>({
    name: '',
    rewardType: 'Discount',
    requiredPoints: '',
    discountValue: '',
    freeProductId: '',
    isActive: true,
    description: '',
  });

  const [showDeleteAlert, setShowDeleteAlert] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<PosRewardCatalogItem | null>(null);

  const [searchText, setSearchText] = useState('');
  const [page, setPage] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const infiniteScrollRef = useRef<HTMLIonInfiniteScrollElement>(null);

  const itemsPerPage = 20;

  const [popoverState, setPopoverState] = useState<{
    showAlertPopover: boolean;
    showMailPopover: boolean;
    event?: Event;
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const fetchCatalogItems = async () => {
    if (!companyId) return;
    setLoading(true);
    setError('');
    try {
      const data = await getAllPosRewardCatalogItems(companyId);
      setCatalogItems(data);
      setPage(0);
      setHasMore(true);
      setFilteredCatalogItems(data.slice(0, itemsPerPage));
    } catch (err) {
      setError((err as Error).message ?? 'Error al cargar los elementos del catálogo.');
      setToastMessage('Error al cargar.');
      setToastColor('danger');
      setShowToast(true);
    } finally {
      setLoading(false);
    }
  };

  useIonViewWillEnter(() => {
    fetchCatalogItems();
  });

  useEffect(() => {
    applySearchFilter();
  }, [searchText, catalogItems]);

  const applySearchFilter = () => {
    const lowerCaseSearchText = searchText.toLowerCase();
    const filtered = catalogItems.filter(
      (item) =>
        item.name.toLowerCase().includes(lowerCaseSearchText) ||
        item.rewardType.toLowerCase().includes(lowerCaseSearchText) ||
        item.description?.toLowerCase().includes(lowerCaseSearchText)
    );
    setFilteredCatalogItems(filtered.slice(0, itemsPerPage));
    setPage(0);
    setHasMore(filtered.length > itemsPerPage);
    infiniteScrollRef.current?.complete();
  };

  const loadMoreItems = async (ev: CustomEvent<void>) => {
    const currentLength = filteredCatalogItems.length;
    const newPage = page + 1;
    const startIndex = newPage * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;

    const lowerCaseSearchText = searchText.toLowerCase();
    const filtered = catalogItems.filter(
      (item) =>
        item.name.toLowerCase().includes(lowerCaseSearchText) ||
        item.rewardType.toLowerCase().includes(lowerCaseSearchText) ||
        item.description?.toLowerCase().includes(lowerCaseSearchText)
    );

    const newItems = filtered.slice(startIndex, endIndex);
    setFilteredCatalogItems((prev) => [...prev, ...newItems]);
    setPage(newPage);

    if (filteredCatalogItems.length + newItems.length >= filtered.length) {
      setHasMore(false);
    }
    (ev.target as HTMLIonInfiniteScrollElement).complete();
  };

  const handleOpenModal = (item?: PosRewardCatalogItem) => {
    if (item) {
      setIsEditing(true);
      setCurrentCatalogItem(item);
      setFormState({
        name: item.name,
        rewardType: item.rewardType,
        requiredPoints: item.requiredPoints,
        discountValue: item.discountValue ?? '',
        freeProductId: item.freeProductId ?? '',
        isActive: item.isActive,
        description: item.description ?? '',
      });
    } else {
      setIsEditing(false);
      setCurrentCatalogItem(null);
      setFormState({
        name: '',
        rewardType: 'Discount',
        requiredPoints: '',
        discountValue: '',
        freeProductId: '',
        isActive: true,
        description: '',
      });
    }
    setShowModal(true);
  };

  const handleCloseModal = () => {
    setShowModal(false);
    setFormState({
      name: '',
      rewardType: 'Discount',
      requiredPoints: '',
      discountValue: '',
      freeProductId: '',
      isActive: true,
      description: '',
    });
  };

  const handleInputChange = (e: CustomEvent<InputInputEventDetail | SelectChangeEventDetail | ToggleChangeEventDetail>) => {
    const { name, value, checked } = e.target as HTMLIonInputElement | HTMLIonSelectElement | HTMLIonToggleElement;

    setFormState((prev) => ({
      ...prev,
      [name!]: name === 'isActive' ? checked : value,
    }));
  };

  const handleSaveCatalogItem = async () => {
    if (!companyId) {
      setError('Company ID no disponible.');
      setToastMessage('Company ID no disponible.');
      setToastColor('danger');
      setShowToast(true);
      return;
    }

    // Basic validation
    if (!formState.name || !formState.requiredPoints || formState.requiredPoints <= 0) {
      setError('Nombre y Puntos Requeridos son obligatorios.');
      setToastMessage('Nombre y Puntos Requeridos son obligatorios.');
      setToastColor('danger');
      setShowToast(true);
      return;
    }

    if (formState.rewardType === 'Discount' && (formState.discountValue === '' || formState.discountValue <= 0)) {
      setError('Valor de Descuento es obligatorio para tipo Descuento.');
      setToastMessage('Valor de Descuento es obligatorio para tipo Descuento.');
      setToastColor('danger');
      setShowToast(true);
      return;
    }

    if (formState.rewardType === 'Product' && (formState.freeProductId === '' || formState.freeProductId <= 0)) {
      setError('ID de Producto Gratuito es obligatorio para tipo Producto.');
      setToastMessage('ID de Producto Gratuito es obligatorio para tipo Producto.');
      setToastColor('danger');
      setShowToast(true);
      return;
    }

    setSaving(true);
    setError('');

    const payload: Omit<PosRewardCatalogItem, "posRewardCatalogItemId" | "created_At" | "updated_at"> = {
      companyId: companyId,
      name: formState.name,
      rewardType: formState.rewardType,
      requiredPoints: Number(formState.requiredPoints),
      discountValue: formState.rewardType === 'Discount' ? (Number(formState.discountValue) || null) : null,
      freeProductId: formState.rewardType === 'Product' ? (Number(formState.freeProductId) || null) : null,
      isActive: formState.isActive,
      description: formState.description || null,
    };

    try {
      if (isEditing && currentCatalogItem) {
        await updatePosRewardCatalogItem(currentCatalogItem.posRewardCatalogItemId, payload);
        setToastMessage('Elemento de catálogo actualizado exitosamente.');
        setToastColor('success');
      } else {
        await createPosRewardCatalogItem(payload);
        setToastMessage('Elemento de catálogo creado exitosamente.');
        setToastColor('success');
      }
      setShowToast(true);
      handleCloseModal();
      fetchCatalogItems();
    } catch (err) {
      setError((err as Error).message ?? 'Error al guardar el elemento del catálogo.');
      setToastMessage('Error al guardar.');
      setToastColor('danger');
      setShowToast(true);
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteClick = (item: PosRewardCatalogItem) => {
    setItemToDelete(item);
    setShowDeleteAlert(true);
  };

  const handleDeleteCatalogItem = async () => {
    if (itemToDelete && companyId) {
      setLoading(true);
      setError('');
      try {
        await deletePosRewardCatalogItem(itemToDelete.posRewardCatalogItemId, companyId);
        setToastMessage('Elemento de catálogo eliminado exitosamente.');
        setToastColor('success');
        setShowToast(true);
        fetchCatalogItems();
      } catch (err) {
        setError((err as Error).message ?? 'Error al eliminar el elemento del catálogo.');
        setToastMessage('Error al eliminar.');
        setToastColor('danger');
        setShowToast(true);
      } finally {
        setLoading(false);
        setItemToDelete(null);
        setShowDeleteAlert(false);
      }
    }
  };

  return (
    <IonPage className="posrewardcatalogitem-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Catálogo de Recompensas — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonSearchbar
          className="posrewardcatalogitem-searchbar"
          placeholder="Buscar recompensa por nombre o tipo"
          value={searchText}
          onIonInput={(e: CustomEvent<SearchbarInputEventDetail>) => setSearchText(e.detail.value!)}
        />

        {loading ? (
          <IonLoading isOpen={loading} message="Cargando elementos..." />
        ) : (
          <IonList className="posrewardcatalogitem-list ion-no-padding">
            {filteredCatalogItems.length === 0 ? (
              <IonItem>
                <IonLabel className="ion-text-center">No hay elementos de catálogo de recompensas disponibles.</IonLabel>
              </IonItem>
            ) : (
              filteredCatalogItems.map((item) => (
                <IonItem key={item.posRewardCatalogItemId} className="posrewardcatalogitem-item">
                  <IonLabel className="ion-text-wrap">
                    <div className="item-header">
                      <h2>{item.name}</h2>
                      <IonButton fill="clear" color="medium" size="small" onClick={() => handleOpenModal(item)}>
                        <IonIcon icon={create} slot="icon-only" />
                      </IonButton>
                    </div>
                    <p>Puntos Requeridos: <strong>{item.requiredPoints.toFixed(2)}</strong></p>
                    <p>
                      Tipo de Recompensa: 
                      <IonLabel className={`reward-type-badge ${item.rewardType.toLowerCase()}`}>
                        {item.rewardType === 'Discount' ? 'Descuento' : 'Producto Gratuito'}
                      </IonLabel>
                    </p>
                    {item.rewardType === 'Discount' && item.discountValue !== null && (
                      <p>Valor de Descuento: <strong>${item.discountValue.toFixed(2)}</strong></p>
                    )}
                    {item.rewardType === 'Product' && item.freeProductId !== null && (
                      <p>ID Producto Gratuito: <strong>{item.freeProductId}</strong></p>
