                    <div className="item-meta">
                      <span>Creado: {toHermosillo(item.created_At)}</span>
                      {item.updated_at && <span>Actualizado: {toHermosillo(item.updated_at)}</span>}
                    </div>
                  </IonLabel>
                  <IonToggle
                    slot="end"
                    checked={item.isActive}
                    color={item.isActive ? 'success' : 'medium'}
                    disabled
                    className="posrewardcatalogitem-toggle"
                  >
                    <IonLabel>{item.isActive ? 'Activo' : 'Inactivo'}</IonLabel>
                  </IonToggle>
                  <IonButton fill="clear" color="danger" slot="end" onClick={() => handleDeleteClick(item)}>
                    <IonIcon icon={trash} slot="icon-only" />
                  </IonButton>
                </IonItem>
              ))
            )}
            <IonInfiniteScroll
              onIonInfinite={loadMoreItems}
              threshold="100px"
              disabled={!hasMore || loading}
              ref={infiniteScrollRef}
            >
              <IonInfiniteScrollContent loadingText="Cargando más elementos..."></IonInfiniteScrollContent>
            </IonInfiniteScroll>
          </IonList>
        )}

        <IonFab vertical="bottom" horizontal="end" slot="fixed">
          <IonFabButton onClick={() => handleOpenModal()}>
            <IonIcon icon={add} />
          </IonFabButton>
        </IonFab>

        <IonModal isOpen={showModal} onDidDismiss={handleCloseModal} className="posrewardcatalogitem-modal">
          <IonHeader>
            <IonToolbar>
              <IonTitle>{isEditing ? 'Editar Recompensa' : 'Crear Nueva Recompensa'}</IonTitle>
              <IonButtons slot="end">
                <IonButton onClick={handleCloseModal}><IonIcon icon={closeCircle} /></IonButton>
              </IonButtons>
            </IonToolbar>
          </IonHeader>
          <IonContent className="ion-padding">
            <div className="posrewardcatalogitem-form-fields">
              <div className="posrewardcatalogitem-field-group">
                <IonInput
                  fill="outline"
                  label="Nombre de la Recompensa *"
                  labelPlacement="floating"
                  name="name"
                  value={formState.name}
                  onIonInput={handleInputChange}
                  className={!formState.name ? 'ion-invalid ion-touched' : ''}
                  errorText={!formState.name ? 'El nombre es obligatorio.' : undefined}
                />
              </div>

              <div className="posrewardcatalogitem-field-group">
                <IonSelect
                  fill="outline"
                  label="Tipo de Recompensa *"
                  labelPlacement="floating"
                  name="rewardType"
                  value={formState.rewardType}
                  onIonChange={handleInputChange}
                  interface="popover"
                  toggleIcon={chevronDown}
                  interfaceOptions={{ cssClass: 'custom-select-popover' }}
                >
                  <IonSelectOption value="Discount">Descuento</IonSelectOption>
                  <IonSelectOption value="Product">Producto Gratuito</IonSelectOption>
                </IonSelect>
              </div>

              <div className="posrewardcatalogitem-field-group">
                <IonInput
                  fill="outline"
                  label="Puntos Requeridos *"
                  labelPlacement="floating"
                  type="number"
                  name="requiredPoints"
                  value={formState.requiredPoints}
                  onIonInput={handleInputChange}
                  className={!formState.requiredPoints || Number(formState.requiredPoints) <= 0 ? 'ion-invalid ion-touched' : ''}
                  errorText={!formState.requiredPoints || Number(formState.requiredPoints) <= 0 ? 'Los puntos son obligatorios y deben ser mayor que 0.' : undefined}
                />
              </div>

              {formState.rewardType === 'Discount' && (
                <div className="posrewardcatalogitem-field-group">
                  <IonInput
                    fill="outline"
                    label="Valor de Descuento * (MXN)"
                    labelPlacement="floating"
                    type="number"
                    name="discountValue"
                    value={formState.discountValue}
                    onIonInput={handleInputChange}
                    className={!formState.discountValue || Number(formState.discountValue) <= 0 ? 'ion-invalid ion-touched' : ''}
                    errorText={!formState.discountValue || Number(formState.discountValue) <= 0 ? 'El valor de descuento es obligatorio y debe ser mayor que 0.' : undefined}
                  />
                </div>
              )}

              {formState.rewardType === 'Product' && (
                <div className="posrewardcatalogitem-field-group">
                  <IonInput
                    fill="outline"
                    label="ID de Producto Gratuito *"
                    labelPlacement="floating"
                    type="number"
                    name="freeProductId"
                    value={formState.freeProductId}
                    onIonInput={handleInputChange}
                    className={!formState.freeProductId || Number(formState.freeProductId) <= 0 ? 'ion-invalid ion-touched' : ''}
                    errorText={!formState.freeProductId || Number(formState.freeProductId) <= 0 ? 'El ID de producto es obligatorio y debe ser mayor que 0.' : undefined}
                  />
                </div>
              )}

              <div className="posrewardcatalogitem-field-group">
                <IonToggle
                  name="isActive"
                  checked={formState.isActive}
                  onIonChange={handleInputChange}
                  justify="space-between"
                  className="posrewardcatalogitem-toggle-modal"
                >
                  <IonLabel>Activo</IonLabel>
                  {formState.isActive ? <IonIcon icon={checkmarkCircle} color="success" slot="end" /> : <IonIcon icon={closeCircle} color="medium" slot="end" />}
                </IonToggle>
              </div>

              <div className="posrewardcatalogitem-field-group">
                <IonInput
                  fill="outline"
                  label="Descripción"
                  labelPlacement="floating"
                  name="description"
                  value={formState.description}
                  onIonInput={handleInputChange}
                />
              </div>
            </div>
          </IonContent>
          <IonFooter className="posrewardcatalogitem-modal-footer">
            <IonToolbar>
              <IonButton expand="block" onClick={handleSaveCatalogItem} disabled={saving || loading}>
                {saving ? <IonSpinner name="dots" /> : (isEditing ? 'Guardar Cambios' : 'Crear Recompensa')}
              </IonButton>
            </IonToolbar>
          </IonFooter>
        </IonModal>

      <IonAlert
        isOpen={showDeleteAlert}
        onDidDismiss={() => setShowDeleteAlert(false)}
        header={'Confirmar Eliminación'}
        message={`¿Estás seguro de que quieres eliminar el elemento de catálogo "${itemToDelete?.name}"?`}
        buttons=[
          { text: 'Cancelar', role: 'cancel' },
          { text: 'Eliminar', handler: handleDeleteCatalogItem, cssClass: 'alert-button-danger' },
        ]
      />

      <IonToast
        isOpen={showToast}
        message={toastMessage}
        duration={3000}
        onDidDismiss={() => setShowToast(false)}
        color={toastColor}
      />
      <IonLoading isOpen={loading && !saving} message="Cargando..." />
      <IonToast
        isOpen={!!error && !showToast}
        message={error}
        duration={3000}
        onDidDismiss={() => setError('')}
        color="danger"
      />
    </IonPage>
  );
};

export default PosRewardCatalogItemPage;
